if (window.top !== window) return;
const stateKey = Symbol.for('openmedia.following-only');
const state = window[stateKey] || (window[stateKey] = { on: false });
state.on = true;
let handled = false;
const select = () => {
  if (!state.on || location.pathname !== '/home') { handled = false; return; }
  if (handled) return;
  const tab = Array.from(document.querySelectorAll('[role="tab"]')).find((item) => item.textContent.trim() === 'Following');
  if (!tab) return;
  handled = true;
  if (tab.getAttribute('aria-selected') !== 'true') tab.click();
};
const timer = setInterval(select, 400);
(window[Symbol.for('openmedia.cleanup')] ||= []).push(() => { state.on = false; clearInterval(timer); });
select();
